const icon=(n,size=20)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${ICONS[n]||ICONS.info}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(s)=>esc(s).replace(/\n/g,' ');
const uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const fmtDate=(s)=>new Date(s).toLocaleString('en-LK',{dateStyle:'medium',timeStyle:'short'});
const fmtTime=(s)=>new Date(s).toLocaleTimeString('en-LK',{hour:'numeric',minute:'2-digit'});
const ago=(s)=>{let m=Math.max(0,Math.floor((Date.now()-new Date(s).getTime())/60000));return m<1?'Just now':m<60?`${m}m ago`:m<1440?`${Math.floor(m/60)}h ago`:`${Math.floor(m/1440)}d ago`};
const CITIES=[{name:'Maharagama',lat:6.8494,lng:79.9275},{name:'Nugegoda',lat:6.8733,lng:79.8911},{name:'Kottawa',lat:6.8434,lng:79.9654},{name:'Pannipitiya',lat:6.8470,lng:79.9488},{name:'Homagama',lat:6.8448,lng:80.0028},{name:'Colombo',lat:6.9271,lng:79.8612},{name:'Dehiwala',lat:6.8511,lng:79.8659},{name:'Battaramulla',lat:6.9006,lng:79.9181},{name:'Kandy',lat:7.2906,lng:80.6337},{name:'Galle',lat:6.0535,lng:80.2210},{name:'Kurunegala',lat:7.4863,lng:80.3647}];
const medicineCatalog=[['Paracetamol','500 mg','Tablet'],['Amoxicillin','500 mg','Capsule'],['Metformin','500 mg','Tablet'],['Atorvastatin','20 mg','Tablet'],['Insulin glargine','100 units/mL','Injection'],['Salbutamol','100 mcg/dose','Inhaler'],['Levothyroxine','50 mcg','Tablet'],['Amlodipine','5 mg','Tablet'],['Losartan','50 mg','Tablet'],['Omeprazole','20 mg','Capsule'],['Montelukast','10 mg','Tablet'],['Cetirizine','10 mg','Tablet']];
const now=()=>new Date().toISOString();
const hrs=(h)=>new Date(Date.now()+h*3600_000).toISOString();
const earlier=(m)=>new Date(Date.now()-m*60_000).toISOString();
const demoPharmacies=[
 {id:'p1',name:'Sample Pharmacy — Maharagama',city:'Maharagama',address:'Demo location, Maharagama',phone:'',lat:6.8494,lng:79.9275,license:'DEMO-001',is_verified:true,is_active:true,stock:['Paracetamol','Metformin','Atorvastatin','Cetirizine']},
 {id:'p2',name:'Sample Pharmacy — Nugegoda',city:'Nugegoda',address:'Demo location, Nugegoda',phone:'',lat:6.8733,lng:79.8911,license:'DEMO-002',is_verified:true,is_active:true,stock:['Paracetamol','Amoxicillin','Salbutamol','Amlodipine']},
 {id:'p3',name:'Sample Pharmacy — Kottawa',city:'Kottawa',address:'Demo location, Kottawa',phone:'',lat:6.8434,lng:79.9654,license:'DEMO-003',is_verified:true,is_active:true,stock:['Paracetamol','Metformin','Losartan','Omeprazole']},
 {id:'p4',name:'Sample Pharmacy — Homagama',city:'Homagama',address:'Demo location, Homagama',phone:'',lat:6.8448,lng:80.0028,license:'DEMO-004',is_verified:true,is_active:true,stock:['Montelukast','Levothyroxine','Salbutamol']},
 {id:'p5',name:'Sample Pharmacy — Pannipitiya',city:'Pannipitiya',address:'Demo location, Pannipitiya',phone:'',lat:6.847,lng:79.9488,license:'DEMO-005',is_verified:true,is_active:true,stock:['Cetirizine','Atorvastatin','Amlodipine']},
 {id:'p6',name:'Sample Pharmacy — Dehiwala',city:'Dehiwala',address:'Demo location, Dehiwala',phone:'',lat:6.8511,lng:79.8659,license:'DEMO-006',is_verified:false,is_active:true,stock:[]},
];
function distanceKm(a,b){if(!a||!b||a.lat==null||b.lat==null)return Infinity;const rad=x=>x*Math.PI/180;const dlat=rad(b.lat-a.lat),dlon=rad(b.lng-a.lng);const q=Math.sin(dlat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q));}
function sampleDB(){let request1={id:'r1',patient_id:'demo',medicine_name:'Metformin',strength:'500 mg',dosage_form:'Tablet',quantity:30,city:'Maharagama',latitude:6.8494,longitude:79.9275,radius_km:10,urgency:'today',status:'open',created_at:earlier(27),expires_at:hrs(8),targets:['p1','p2','p3','p5']};let request2={id:'r2',patient_id:'demo',medicine_name:'Salbutamol',strength:'100 mcg/dose',dosage_form:'Inhaler',quantity:1,city:'Nugegoda',latitude:6.8733,longitude:79.8911,radius_km:10,urgency:'today',status:'open',created_at:earlier(65),expires_at:hrs(7),targets:['p1','p2','p3','p5']};let request3={id:'r3',patient_id:'demo',medicine_name:'Levothyroxine',strength:'50 mcg',dosage_form:'Tablet',quantity:30,city:'Maharagama',latitude:6.8494,longitude:79.9275,radius_km:10,urgency:'soon',status:'open',created_at:earlier(13),expires_at:hrs(11),targets:['p1','p2','p3','p5']};return{pharmacies:demoPharmacies,requests:[request1,request2,request3],responses:[{id:'resp1',request_id:'r1',pharmacy_id:'p1',status:'available',note:'Sample stock indication only; confirm directly.',confirmed_at:earlier(16),expires_at:hrs(.25)}]};}
function loadDemo(){try{const data=JSON.parse(localStorage.getItem('medifind_demo_v01'));if(data?.pharmacies&&data?.requests&&data?.responses)return data;}catch{}return sampleDB();}
const state={page:'home',modal:null,mode:'demo',role:'patient',activePharmacy:'p1',term:'',city:'Maharagama',filter:'all',urgentOnly:false,language:'en',data:loadDemo(),session:null,profile:null,assignedPharmacies:[],busy:false,notice:'',authMode:'signin',liveError:'',lastSearch:false,medSearch:'',toastTimer:null};
function saveDemo(){if(state.mode==='demo'){try{localStorage.setItem('medifind_demo_v01',JSON.stringify(state.data));}catch(e){console.warn('Browser storage unavailable; demo changes will only last for this session.',e);}}}
function cityPoint(city){return CITIES.find(c=>c.name===city)||CITIES[0];}
function cityOptions(sel){return CITIES.map(x=>`<option value="${esc(x.name)}" ${sel===x.name?'selected':''}>${esc(x.name)}</option>`).join('');}
function currentPharmacies(){return state.data.pharmacies.filter(x=>x.is_verified&&x.is_active!==false);}
function requestOpen(r){return r.status==='open'&&new Date(r.expires_at)>new Date();}
function requestLabel(s){return({available:'Available',limited:'Limited stock',unavailable:'Unavailable',open:'Looking for stock',fulfilled:'Found medicine',cancelled:'Cancelled',expired:'Expired'})[s]||s;}
function requestBadge(s){const k=s==='available'||s==='fulfilled'?'':s==='limited'||s==='today'?'orange':s==='unavailable'||s==='cancelled'?'red':'grey';return `<span class="badge ${k}">${esc(requestLabel(s))}</span>`;}
function responseValid(r){return r.status!=='unavailable'&&new Date(r.expires_at)>new Date();}
function targetPharmacies(req,pharmacies){const p={lat:req.latitude,lng:req.longitude};return pharmacies.filter(x=>x.is_verified&&x.is_active!==false&&(distanceKm(p,x)<=req.radius_km||(x.city===req.city&&(x.lat==null||req.latitude==null)))).map(x=>x.id);}
function requestsForActivePharmacy(){if(state.mode==='demo')return state.data.requests.filter(r=>r.targets.includes(state.activePharmacy)&&requestOpen(r));return (state.data.incoming||[]).filter(r=>r.pharmacy_id===state.activePharmacy);}
function pharmacyById(id){return state.data.pharmacies.find(p=>p.id===id);}
function responsesForRequest(r){return state.data.responses.filter(x=>x.request_id===r.id);}
function activePharmacy(){return pharmacyById(state.activePharmacy);}
function toast(message){const previous=document.querySelector('.toast');previous?.remove();const el=document.createElement('div');el.className='toast';el.innerHTML=`${icon('check',17)}<span>${esc(message)}</span>`;document.body.appendChild(el);clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.remove(),4000);}
function nav(page){state.page=page;state.modal=null;state.lastSearch=false;state.filter='all';render();window.scrollTo({top:0,behavior:'smooth'});if(state.mode==='live')refreshLive().catch(showError);}
function showError(err){console.error(err);toast(err?.message||'Something went wrong. Please try again.');}
function layout(pageContent){const role=state.role;const navItems=[['home','Home','home'],['find','Find a medicine','search'],['requests','My requests','clipboard'],['pharmacy','Pharmacy portal','pharmacy'],['admin','Admin dashboard','shield']];const activeNav=state.page;const navButton=(n,mobile=false)=>`<button class="${mobile?'':'nav-item '}${activeNav===n[0]?'active':''}" data-nav="${n[0]}" title="${esc(n[1])}">${icon(n[2],mobile?21:18)}${mobile?`<span>${n[1].replace(' a medicine','').replace(' portal','').replace(' dashboard','')}</span>`:`<span>${n[1]}</span>`}${!mobile&&n[0]==='requests'&&state.data.requests.length?`<small class="nav-count">${state.data.requests.length}</small>`:''}</button>`;
return `<div class="app-shell"><aside class="sidebar"><div class="logo"><div class="logo-mark">${icon('cross',20)}</div><div><div class="logo-main">medi<span>find</span><em>.lk</em></div><div class="logo-sub">Find medicine. Find relief.</div></div></div><div class="side-label">MAIN MENU</div><nav class="nav-list">${navItems.map(n=>navButton(n)).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><div class="help-icon">${icon('heart',20)}</div><h4>Here to help you.</h4><p>Find medicine faster with nearby pharmacies ready to respond.</p><button data-nav="about">How it works ${icon('arrow',12)}</button></div><div class="side-footer">© 2026 MediFind LK · Prototype v0.1</div></div></aside><main class="main"><header class="topbar"><div class="crumb">MediFind LK <span style="color:#bccbc6;margin:0 8px">/</span> <b>${esc({home:'Dashboard',find:'Find medicine',requests:'My requests',pharmacy:'Pharmacy portal',admin:'Admin',about:'How it works'}[state.page]||'Home')}</b></div><div class="topbar-logo"><div class="logo-mark" style="width:31px;height:31px;border-radius:10px">${icon('cross',17)}</div>medifind<span style="color:#078375">.lk</span></div><div class="top-actions"><span class="pill-indicator ${state.mode==='demo'?'demo':''}"><span class="dot"></span>${state.mode==='demo'?'Demo mode':'Live connected'}</span>${state.mode==='live'?`<button class="top-plain" data-action="account" title="Account">${icon('user',19)}</button>`:''}<button class="avatar" data-action="account" title="Account">${state.session?.user?.email?esc(state.session.user.email[0].toUpperCase()):'MF'}</button></div></header><div class="content">${state.mode==='demo'?`<div class="demo-banner" style="margin-bottom:21px">${icon('info',16)}<span><b>Interactive prototype.</b> All pharmacies, stock indicators, requests and confirmations are sample data stored in your browser. No real availability is being reported. <button class="role-button" data-action="setup">Connect Supabase</button></span></div>`:''}${pageContent}<div class="safety-footer">${icon('shield',19)}<span><b>Important:</b> MediFind is a medicine availability enquiry tool, not a medical advice or dispensing service. Stock indications are time-sensitive. Always confirm with a licensed pharmacist, present a valid prescription when required, and seek emergency medical care for urgent medical situations. Do not share prescriptions or personal medical information in the demo.</span></div><div class="footer-note">MediFind LK v0.1 · Pilot prototype · Built for Sri Lanka</div></div></main><nav class="mobile-nav">${[navItems[0],navItems[1],navItems[2],navItems[3],navItems[4]].map(n=>navButton(n,true)).join('')}</nav></div>${state.modal?modalHTML():''}`;}
function sectionTitle(title,subtitle,action,actionPage){return `<div class="section-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${action?`<button class="text-btn" data-nav="${actionPage}">${esc(action)} ${icon('arrow',15)}</button>`:''}</div>`;}
function hero(){return `<section class="hero"><div class="hero-glow"></div><div class="hero-content"><span class="eyebrow">YOUR HEALTH, OUR PRIORITY</span><h1>Find the medicine<br/>you need, <span style="color:#bcf6df">faster.</span></h1><p>Stop calling pharmacy after pharmacy. Send one request and let nearby participating pharmacies respond to you.</p><div class="hero-actions"><button class="btn btn-white" data-action="new-request">${icon('plus',17)} Request medicine</button><button class="btn" style="background:#ffffff25;border:1px solid #ffffff55" data-nav="about">How it works ${icon('arrow',15)}</button></div></div><div class="hero-art"><div class="hero-circle"></div><div class="capsule"></div><div class="sparkle s1">✧</div><div class="sparkle s2">✦</div></div></section>`;}
function searchPanel(){return `<form class="search-panel" id="searchForm"><div class="field" style="flex:2"><label>Medicine name</label><div class="input-wrap">${icon('search',17)}<input name="medicine" id="homeMedicine" value="${val(state.term)}" autocomplete="off" placeholder="Search a medicine (e.g. Metformin)" aria-label="Medicine name"/></div></div><div class="field field-small"><label>Your area</label><select name="city" aria-label="Your area">${cityOptions(state.city)}</select></div><button class="btn" type="submit" style="min-width:140px">${icon('search',16)} Find medicine</button></form>`;}
function stats(){return `<div class="stats"><div class="stat"><div class="stat-ico">${icon('pharmacy',21)}</div><div><h3>${currentPharmacies().length}</h3><p>${state.mode==='demo'?'Sample pharmacies':'Verified pharmacies'}</p></div></div><div class="stat"><div class="stat-ico amber">${icon('clipboard',21)}</div><div><h3>${state.data.requests.filter(requestOpen).length}</h3><p>${state.mode==='demo'?'Sample active requests':'Your active requests'}</p></div></div><div class="stat"><div class="stat-ico blue">${icon('check',23)}</div><div><h3>${state.data.responses.filter(responseValid).length}</h3><p>Active confirmations</p></div></div></div>`;}
function homePage(){const recent=state.data.requests.slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,3);return `${hero()}${searchPanel()}${stats()}${sectionTitle('Your health, made simpler','A few steps from a request to a pharmacy response.')}
<div class="features"><div class="feature">${icon('search',25)}<h3>Search medicines</h3><p>Explore local medicine enquiries and find participating pharmacies near your selected area.</p><button class="text-btn" data-nav="find">Explore pharmacies ${icon('arrow',14)}</button></div><div class="feature">${icon('clipboard',25)}<h3>Send a request</h3><p>Tell pharmacies exactly what you need: name, strength, dosage form and quantity.</p><button class="text-btn" data-action="new-request">Create a request ${icon('arrow',14)}</button></div><div class="feature">${icon('bell',25)}<h3>Get confirmations</h3><p>Pharmacy staff can confirm recent stock indications so you know whom to contact.</p><button class="text-btn" data-nav="requests">Track requests ${icon('arrow',14)}</button></div></div>
${sectionTitle('Recent medicine requests','Track requests and pharmacy responses.','View all requests','requests')}
<div class="main-grid"><div class="panel">${recent.length?recent.map(r=>`<div class="list-item"><div class="pharmacy-ico">${icon('clipboard',20)}</div><div class="grow"><div class="request-title">${esc(r.medicine_name)} ${esc(r.strength||'')}</div><div class="meta">${esc(r.city)} · ${ago(r.created_at)} · ${r.quantity} requested</div></div>${requestBadge(requestOpen(r)?'open':r.status)}</div>`).join(''):empty('No requests yet','Start by sending your first medicine enquiry.','clipboard')}</div>
<div class="callout"><div class="callout-icon">${icon('pharmacy',29)}</div><div><h3>Are you a pharmacy?</h3><p>Respond to requests and help patients find medicines.</p><button class="btn btn-sm" data-nav="pharmacy">Open pharmacy portal ${icon('arrow',13)}</button></div></div></div>`;}
function pharmacyCard(p,term,center){const d=distanceKm(cityPoint(center),p);const hasSample=state.mode==='demo'&&p.stock?.some(s=>s.toLowerCase()===term.toLowerCase());return `<div class="pharmacy-card"><div class="pharmacy-ico">${icon('pharmacy',22)}</div><div><h3>${esc(p.name)}</h3><div class="meta">${icon('pin',12)} ${esc(p.city)} ${Number.isFinite(d)?` · ${d.toFixed(1)} km from area centre`:''}</div><div class="desc">${esc(p.address||p.city)} ${state.mode==='demo'?'· Fictitious listing':''}</div><div class="row" style="margin-top:12px;flex-wrap:wrap"><button class="btn btn-sm" data-action="new-request" data-medicine="${esc(term)}">${icon('clipboard',13)} Request availability</button>${p.phone?`<a class="btn btn-outline btn-sm" href="tel:${esc(p.phone)}">${icon('phone',13)} Call</a>`:''}${state.mode==='live'&&p.address?`<a class="btn btn-outline btn-sm" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.address+' '+p.city+' Sri Lanka')}">${icon('route',13)} Directions</a>`:''}</div></div><div class="result-status"><span class="badge ${hasSample?'orange':'grey'}">${state.mode==='demo'?(hasSample?'Sample stock':'No sample stock'):'Stock unconfirmed'}</span><span class="sub">${state.mode==='demo'?'Not real-time availability':'Ask pharmacy to confirm'}</span></div></div>`;}
function findPage(){const term=state.term.trim();let pharmacies=currentPharmacies().map(p=>({...p,dist:distanceKm(cityPoint(state.city),p)})).filter(p=>state.filter==='all'||p.city===state.city).sort((a,b)=>a.dist-b.dist);const matches=medicineCatalog.filter(x=>!term||x.join(' ').toLowerCase().includes(term.toLowerCase())).slice(0,5);return `<div class="toolbar"><div><div class="eyebrow">SEARCH & DISCOVER</div><h1>Find a medicine</h1><p>Browse the pharmacy network and request confirmation of availability.</p></div><button class="btn" data-action="new-request">${icon('plus',16)} New request</button></div>${searchPanel()}<div class="search-summary"><div><h3>${term?`Searching for “${esc(term)}”`:'Nearby pharmacies'}</h3><p class="muted sm" style="margin-top:6px">${pharmacies.length} ${state.mode==='demo'?'sample':'verified'} pharmacies listed · ${esc(state.city)}</p></div><button class="text-btn" data-action="new-request">Can't find it? Request availability ${icon('arrow',14)}</button></div>${term&&matches.length?`<div class="panel" style="margin-bottom:20px"><div class="result-bar"><b class="sm">Medicine catalogue suggestions</b><span class="badge grey">Names are not medical advice</span></div>${matches.map(m=>`<button class="medicine-pick" data-action="select-medicine" data-medicine="${esc(m[0])}" data-strength="${esc(m[1])}" data-form="${esc(m[2])}"><span><b>${esc(m[0])}</b> <small class="muted">${esc(m[1])} · ${esc(m[2])}</small></span>${icon('chevron',15)}</button>`).join('')}</div>`:''}<div class="filter-row"><button class="chip ${state.filter==='all'?'active':''}" data-filter="all">All nearby</button><button class="chip ${state.filter==='city'?'active':''}" data-filter="city">Only ${esc(state.city)}</button></div><div class="panel"><div class="result-bar"><span class="sm"><b>Participating pharmacies</b></span><span class="sm muted">${state.mode==='demo'?'Sample directory':'Verified directory'}</span></div>${pharmacies.length?pharmacies.map(p=>pharmacyCard(p,term,state.city)).join(''):empty('No pharmacies in this filter','Try another area or expand the view.','pin')}</div><div class="notice" style="margin-top:17px">${icon('info',18)}<span>Search results are pharmacy listings, not confirmation that a medicine is stocked. Only a recent explicit pharmacist response can be treated as an availability indication; always call before travelling.</span></div>`;}
function requestCard(r){const responses=responsesForRequest(r).slice().sort((a,b)=>new Date(b.confirmed_at)-new Date(a.confirmed_at));const status=requestOpen(r)?'open':r.status==='open'?'expired':r.status;const approved=responses.filter(responseValid);return `<div class="request-card"><div class="row-between"><div><div class="request-title">${esc(r.medicine_name)} · ${esc(r.strength||'Not specified')}</div><div class="meta">${esc(r.dosage_form||'Form not specified')} · Qty ${esc(r.quantity)} · ${esc(r.city)}</div></div>${requestBadge(status)}</div><div class="meta" style="margin-top:12px">${icon('clock',12)} Submitted ${fmtDate(r.created_at)} · ${esc(r.urgency==='today'?'Needed today':'Needed soon')}</div>${responses.length?`<div class="response-list">${responses.map(x=>{const p=pharmacyById(x.pharmacy_id);const fresh=responseValid(x);return `<div class="response"><div class="row-between"><b class="sm">${esc(p?.name||'Pharmacy')}</b>${fresh?requestBadge(x.status):`<span class="badge grey">Expired / outdated</span>`}</div><p>${esc(x.note||'Availability status recorded.')} · Responded ${ago(x.confirmed_at)}${x.status!=='unavailable'?` · Valid until ${fmtTime(x.expires_at)}`:''}</p>${fresh&&p?.phone?`<a class="btn btn-sm btn-outline" style="margin-top:11px" href="tel:${esc(p.phone)}">${icon('phone',13)} Contact pharmacy</a>`:''}</div>`}).join('')}</div>`:`<div class="notice" style="margin-top:14px">${icon('clock',15)}<span>Waiting for a participating pharmacy to respond. Do not rely on an enquiry for urgent clinical care.</span></div>`}<div class="row" style="margin-top:13px;justify-content:space-between"><span class="small-code">${esc(r.id.slice(0,8))}</span>${requestOpen(r)?`<button class="delete-btn" data-action="cancel-request" data-id="${esc(r.id)}">Cancel request</button>`:''}</div></div>`;}
function requestsPage(){const rs=state.data.requests.slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));return `<div class="toolbar"><div><div class="eyebrow">YOUR ENQUIRIES</div><h1>My requests</h1><p>See responses and follow up directly with pharmacies.</p></div><button class="btn" data-action="new-request">${icon('plus',15)} New request</button></div><div class="tiles" style="margin-bottom:20px"><div class="info-tile"><div class="caption">Total requests</div><div class="value">${rs.length}</div></div><div class="info-tile"><div class="caption">Looking for stock</div><div class="value">${rs.filter(requestOpen).length}</div></div><div class="info-tile"><div class="caption">Recent confirmations</div><div class="value">${state.data.responses.filter(responseValid).length}</div></div></div><div class="panel">${rs.length?rs.map(requestCard).join(''):empty('No requests yet','Submit a medicine name and area to get started.','clipboard')}</div>`;}
function pharmacyPage(){const p=activePharmacy();const requests=requestsForActivePharmacy().slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));const responses=state.data.responses.filter(x=>x.pharmacy_id===state.activePharmacy);const pharmacies=state.mode==='demo'?state.data.pharmacies.filter(p=>p.is_verified):state.assignedPharmacies;return `<div class="toolbar"><div><div class="eyebrow">PHARMACY WORKSPACE</div><h1>Pharmacy portal</h1><p>Help people in your area locate medicines faster.</p></div>${state.mode==='demo'?`<span class="badge orange">Simulation: no real stock</span>`:''}</div>${state.mode==='live'&&!state.session?`<div class="notice orange" style="margin-bottom:20px">${icon('info',17)}<span>Sign in with a staff account assigned by the MediFind administrator before responding to medicine requests. <button class="role-button" data-action="account">Sign in</button></span></div>`:''}${state.mode==='live'&&state.session&&!pharmacies.length?`<div class="notice orange" style="margin-bottom:20px">${icon('info',17)}<span>Your account is not assigned to a pharmacy. An administrator must add your user ID to <code>pharmacy_staff</code> and verify the pharmacy.</span></div>`:''}${pharmacies.length?`<div class="panel pad" style="margin-bottom:19px"><div class="row-between" style="flex-wrap:wrap"><div class="row"><div class="pharmacy-ico">${icon('pharmacy',22)}</div><div><b>${esc(p?.name||'Select pharmacy')}</b><p class="sm muted">${esc(p?.city||'')} ${state.mode==='demo'?'· Demo account':''}</p></div></div><div class="field" style="max-width:265px"><select id="pharmacyPicker" aria-label="Select pharmacy">${pharmacies.map(x=>`<option value="${esc(x.id)}" ${x.id===state.activePharmacy?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div></div>`:''}<div class="tiles" style="margin-bottom:19px"><div class="info-tile"><div class="caption">Incoming requests</div><div class="value">${requests.length}</div></div><div class="info-tile"><div class="caption">Responded</div><div class="value">${responses.length}</div></div><div class="info-tile"><div class="caption">Available responses</div><div class="value">${responses.filter(r=>r.status==='available').length}</div></div></div><div class="panel"><div class="result-bar"><div><b class="panel-title">Incoming medicine enquiries</b><div class="footer-small">Only respond after checking actual inventory.</div></div><button class="text-btn" data-action="refresh">${icon('clock',14)} Refresh</button></div>${requests.length?requests.map(r=>{const response=responses.find(x=>x.request_id===r.id);return `<div class="pharmacy-req"><div class="row-between"><div><h3>${esc(r.medicine_name)} ${esc(r.strength||'')}</h3><div class="meta">${esc(r.dosage_form||'Form unspecified')} · Qty ${esc(r.quantity)} · ${esc(r.city)}</div></div>${response?requestBadge(response.status):`<span class="badge orange">Awaiting response</span>`}</div><div class="meta" style="margin-top:12px">${icon('clock',12)} ${ago(r.created_at)} · ${r.urgency==='today'?'Needed today':'Needed soon'}</div><div class="action-row"><button class="btn btn-sm" data-action="respond" data-id="${esc(r.id)}" data-status="available">${icon('check',13)} Available</button><button class="btn btn-sm btn-warn" data-action="respond" data-id="${esc(r.id)}" data-status="limited">Limited stock</button><button class="btn btn-sm btn-outline" data-action="respond" data-id="${esc(r.id)}" data-status="unavailable">Unavailable</button></div>${response?`<div class="footer-small">Last response: ${fmtDate(response.confirmed_at)}</div>`:''}</div>`}).join(''):empty('No incoming requests','Matching requests will appear here when patients send medicine enquiries in your area.','bell')}</div><div class="notice" style="margin-top:18px">${icon('shield',17)}<span>Only authorised pharmacy staff may confirm stock. A positive availability response expires after 30 minutes, and patients must still contact the pharmacy before visiting. Prescription medicines require pharmacist verification and a valid prescription.</span></div>`;}
function adminPage(){const data=state.data;const verified=data.pharmacies.filter(p=>p.is_verified).length;const adminAllowed=state.mode==='demo'||state.profile?.role==='admin';return `<div class="toolbar"><div><div class="eyebrow">NETWORK MANAGEMENT</div><h1>Admin dashboard</h1><p>Verify pharmacies, review network coverage and protect patients.</p></div>${adminAllowed?`<button class="btn" data-action="new-pharmacy">${icon('plus',16)} Add pharmacy</button>`:''}</div>${!adminAllowed?`<div class="notice orange">${icon('shield',17)}<span>Administrative access is restricted. Your account does not have the admin role.</span></div>`:`<div class="tiles" style="margin-bottom:20px"><div class="info-tile"><div class="caption">Total pharmacies</div><div class="value">${data.pharmacies.length}</div></div><div class="info-tile"><div class="caption">Verified pharmacies</div><div class="value">${verified}</div></div><div class="info-tile"><div class="caption">Patient enquiries</div><div class="value">${data.requests.length}</div></div></div><div class="panel"><div class="result-bar"><b class="panel-title">Pharmacy directory</b><span class="badge grey">${data.pharmacies.length} records</span></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>Pharmacy</th><th>Location</th><th>Licence reference</th><th>Status</th><th>Action</th></tr></thead><tbody>${data.pharmacies.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(p.city)}</td><td>${esc(p.license||'Not provided')}</td><td><span class="badge ${p.is_verified?'':'orange'}">${p.is_verified?'Verified':'Pending review'}</span></td><td><button class="btn btn-outline btn-sm" data-action="toggle-verify" data-id="${esc(p.id)}">${p.is_verified?'Revoke':'Verify'}</button></td></tr>`).join('')}</tbody></table></div></div><div class="notice orange" style="margin-top:19px">${icon('alert',17)}<span>${state.mode==='demo'?'Verification changes here are local simulation only.':'Before verifying any real pharmacy, independently confirm its currently valid NMRA licence and contact information.'} Do not treat a licence number entered by a business as proof of verification.</span></div>`}`;}
function aboutPage(){return `<div class="toolbar"><div><div class="eyebrow">ABOUT MEDIFIND LK</div><h1>Better access to medicines.</h1><p>One request, multiple participating pharmacies, clear responses.</p></div><button class="btn" data-action="new-request">${icon('plus',15)} Make a request</button></div><div class="panel pad" style="margin-bottom:20px;background:linear-gradient(110deg,#f0fbf5,#fff)"><h2 style="max-width:600px">No more asking dozens of people to find one medicine.</h2><p class="sm muted" style="max-width:620px;margin-top:11px">MediFind is being designed around a simple observation: Sri Lankan families often resort to Facebook and WhatsApp posts when a medicine is hard to find. Our goal is to make pharmacy enquiries faster and more reliable.</p></div><div class="about-list"><div>${icon('search',22)}<h4 style="margin-top:12px">1. Describe your medicine</h4><p>Enter the name, strength, dosage form and the area where you need it.</p></div><div>${icon('bell',22)}<h4 style="margin-top:12px">2. Nearby pharmacies see the request</h4><p>Verified pharmacies in the matching search area receive it in their dashboard.</p></div><div>${icon('check',22)}<h4 style="margin-top:12px">3. Staff confirm stock</h4><p>Pharmacy staff can report available, limited, or unavailable.</p></div><div>${icon('phone',22)}<h4 style="margin-top:12px">4. You contact the pharmacy</h4><p>Call to reconfirm stock and ask about prescription requirements before travelling.</p></div></div><div class="notice" style="margin-top:24px">${icon('info',18)}<span>Prototype v0.1 does not offer sales, deliveries, prescription uploads, medical treatment recommendations or automatic medicine substitution. No actual pharmacies are onboarded through the demo database.</span></div>`;}
function empty(title,message,i='search'){return `<div class="empty">${icon(i,30)}<h3>${esc(title)}</h3><p>${esc(message)}</p></div>`;}
function render(){let c=({home:homePage,find:findPage,requests:requestsPage,pharmacy:pharmacyPage,admin:adminPage,about:aboutPage})[state.page]?.()||homePage();$app.innerHTML=layout(c);}
function modalHTML(){const m=state.modal;const top=(title,sub)=>`<div class="modal-header"><div><div class="eyebrow" style="margin-bottom:6px">${esc(sub||'MEDIFIND LK')}</div><h2>${esc(title)}</h2></div><button class="close" data-action="close-modal" aria-label="Close">${icon('close',19)}</button></div>`;let body='';
if(m.type==='request'){const defaults=medicineCatalog.find(x=>x[0].toLowerCase()===(m.medicine||state.term).toLowerCase());body=`${top('Request medicine','SEND AN ENQUIRY')}<form id="requestForm"><div class="modal-body"><div class="notice" style="margin-bottom:17px">${icon('info',17)}<span>Enter the exact medicine name and strength from the original prescription or packaging. Pharmacy staff must verify details before dispensing.</span></div><div class="form-grid"><div class="field"><label>Medicine name <span class="required">*</span></label><input name="medicine_name" maxlength="120" value="${val(m.medicine||state.term)}" required placeholder="e.g. Metformin"/></div><div class="field"><label>Strength <span class="required">*</span></label><input name="strength" maxlength="50" value="${val(m.strength||defaults?.[1]||'')}" required placeholder="e.g. 500 mg"/></div><div class="field"><label>Dosage form <span class="required">*</span></label><select name="dosage_form" required>${['Tablet','Capsule','Syrup','Injection','Inhaler','Cream / ointment','Drops','Other'].map(x=>`<option ${x===(m.form||defaults?.[2]||'Tablet')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Quantity <span class="required">*</span></label><input name="quantity" type="number" min="1" max="999" required value="1"/></div><div class="field"><label>Nearest town <span class="required">*</span></label><select name="city" required>${cityOptions(state.city)}</select></div><div class="field"><label>Search radius</label><select name="radius_km"><option value="5">5 km</option><option value="10" selected>10 km</option><option value="20">20 km</option><option value="25">25 km</option></select></div><div class="field" style="grid-column:1/-1"><label>When do you need it?</label><select name="urgency"><option value="today">Today</option><option value="soon">Within the next few days</option></select></div></div><div class="field-note" style="margin-top:13px">We do not collect diagnosis, prescription photos, date of birth or other sensitive health details in this initial prototype. Requests automatically expire after 12 hours.</div><div id="requestError" role="alert"></div></div><div class="modal-foot"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn">${icon('arrow',15)} ${state.mode==='demo'?'Simulate request':'Send request'}</button></div></form>`;}
else if(m.type==='respond'){const req=state.data.requests.find(r=>r.id===m.id)||state.data.incoming?.find(r=>r.id===m.id);body=`${top('Confirm availability','PHARMACY RESPONSE')}<form id="responseForm"><div class="modal-body"><div class="notice ${state.mode==='demo'?'orange':''}" style="margin-bottom:17px">${icon('alert',18)}<span>${state.mode==='demo'?'This is a simulated pharmacy response. It does not represent actual stock.':'Only respond after physically checking the exact medicine, dosage form, strength and requested quantity. A positive response expires automatically after 30 minutes.'}</span></div><div class="panel pad" style="margin-bottom:16px"><h3>${esc(req?.medicine_name||'Medicine')} ${esc(req?.strength||'')}</h3><p class="meta">${esc(req?.dosage_form||'')} · Quantity: ${esc(req?.quantity||'')} · ${esc(req?.city||'')}</p></div><div class="field"><label>Status</label><input value="${esc(requestLabel(m.status))}" disabled/></div><div class="field" style="margin-top:15px"><label>Optional note (no personal information)</label><textarea maxlength="240" name="note" placeholder="e.g. Call before collection to reconfirm."></textarea></div>${state.mode==='live'?`<label class="row sm" style="margin-top:18px;align-items:start"><input type="checkbox" name="verified_stock" required style="margin-top:3px"/> I checked the exact requested medicine and quantity against current pharmacy stock.</label>`:''}<div id="responseError" role="alert"></div></div><div class="modal-foot"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn">${icon('check',16)} ${state.mode==='demo'?'Simulate response':'Confirm response'}</button></div></form>`;}
else if(m.type==='pharmacy'){body=`${top('Add a pharmacy','NETWORK MANAGEMENT')}<form id="pharmacyForm"><div class="modal-body"><div class="form-grid"><div class="field" style="grid-column:1/-1"><label>Business name *</label><input name="name" maxlength="100" required placeholder="Registered pharmacy name"/></div><div class="field"><label>Town *</label><select name="city" required>${cityOptions(state.city)}</select></div><div class="field"><label>Licence reference *</label><input name="license" maxlength="80" required placeholder="NMRA retail pharmacy licence"/></div><div class="field" style="grid-column:1/-1"><label>Address *</label><input name="address" maxlength="200" required placeholder="Street, town"/></div><div class="field" style="grid-column:1/-1"><label>Telephone (optional)</label><input name="phone" type="tel" maxlength="30" placeholder="e.g. +94..."/></div></div><div class="notice orange" style="margin-top:16px">${icon('alert',16)}<span>All new pharmacies are added as pending verification. Check the official NMRA register independently before granting access.</span></div><div id="pharmacyError" role="alert"></div></div><div class="modal-foot"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn">Add for review</button></div></form>`;}
else if(m.type==='auth'){body=`${top(state.authMode==='signup'?'Create an account':'Welcome back','SECURE ACCOUNT')}<form id="authForm"><div class="modal-body"><div class="pill-tabs" style="margin-bottom:20px"><button type="button" data-action="auth-switch" data-authmode="signin" class="${state.authMode==='signin'?'active':''}">Sign in</button><button type="button" data-action="auth-switch" data-authmode="signup" class="${state.authMode==='signup'?'active':''}">Create account</button></div>${state.authMode==='signup'?`<div class="field" style="margin-bottom:13px"><label>Your display name *</label><input name="display_name" maxlength="80" required placeholder="Your name" autocomplete="name"/></div>`:''}<div class="field" style="margin-bottom:13px"><label>Email address *</label><input type="email" name="email" required autocomplete="email" placeholder="you@example.com"/></div><div class="field"><label>Password *</label><input type="password" name="password" required minlength="8" autocomplete="${state.authMode==='signup'?'new-password':'current-password'}" placeholder="Minimum 8 characters"/></div><div id="authError" role="alert"></div><div class="field-note" style="margin-top:16px">MediFind currently supports email authentication for the pilot. Pharmacy access requires administrator approval.</div></div><div class="modal-foot"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn" type="submit">${state.authMode==='signup'?'Create account':'Sign in'}</button></div></form>`;}
else if(m.type==='account'){body=`${top('Your account','PROFILE & SETTINGS')}<div class="modal-body">${state.mode==='demo'?`<div class="notice orange">${icon('info',17)}<span>You're exploring demo mode. The data you create is saved only in this browser. To enable real user accounts, configure Supabase.</span></div><div style="margin-top:18px" class="stack"><button class="btn btn-full" data-action="setup">Configure a live backend</button><button class="btn btn-outline btn-full" data-action="reset-demo">Reset demo data</button></div>`:state.session?`<div class="panel pad"><b>${esc(state.profile?.display_name||'MediFind member')}</b><p class="muted sm" style="margin-top:7px">${esc(state.session.user.email)}</p><p class="footer-small">Role: ${esc(state.profile?.role||'patient')} · ID: ${esc(state.session.user.id.slice(0,8))}…</p></div><button class="btn btn-outline btn-full" style="margin-top:17px" data-action="signout">${icon('logout',16)} Sign out</button>`:`<p class="muted sm">Sign in to create requests and track pharmacy confirmations.</p><button class="btn btn-full" style="margin-top:15px" data-action="login">Sign in or register</button>`}</div>`;}
else if(m.type==='setup'){body=`${top('Connect the live backend','PROJECT SETUP')}<div class="modal-body"><div class="notice orange">${icon('info',17)}<span>Current mode: <b>${state.mode==='demo'?'demo only':'Supabase connected'}</b>. Do not use demo mode to locate real medicine stock.</span></div><div class="stack" style="margin-top:18px"><p class="sm"><b>1.</b> Create a Supabase project.</p><p class="sm"><b>2.</b> Run <code>supabase/schema.sql</code> in the SQL editor.</p><p class="sm"><b>3.</b> Duplicate <code>config.example.js</code> as <code>config.js</code>.</p><p class="sm"><b>4.</b> Enter the Supabase project URL and publishable/anon key in that file.</p><p class="sm"><b>5.</b> Reload the site. The header should show “Live connected”.</p></div><div class="notice" style="margin-top:18px">${icon('shield',17)}<span>Never expose a Supabase service_role key in the browser. Real pharmacy listings remain hidden until an admin verifies their licence.</span></div></div><div class="modal-foot"><button class="btn" data-action="close-modal">Understood</button></div>`;}
return `<div class="modal-overlay" data-action="dismiss-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(m.type)}">${body}</div></div>`;}
function openModal(type,props={}){if(state.mode==='live'&&type==='request'&&!state.session){state.authMode='signin';state.modal={type:'auth'};render();toast('Sign in first to create a request.');return;}state.modal={type,...props};render();}
function errorIn(id,message){const n=document.getElementById(id);if(n)n.innerHTML=message?`<div class="form-error">${esc(message)}</div>`:'';}
async function submitRequest(form){const d=new FormData(form);const city=d.get('city'),point=cityPoint(city);const medicine=String(d.get('medicine_name')||'').trim();const strength=String(d.get('strength')||'').trim();const dosage_form=String(d.get('dosage_form')||'').trim();const quantity=Number(d.get('quantity'));const radius_km=Number(d.get('radius_km'));const urgency=d.get('urgency');if(!medicine||medicine.length>120||!strength||strength.length>50||!Number.isInteger(quantity)||quantity<1||quantity>999)return errorIn('requestError','Please provide a valid medicine, strength and quantity.');const req={patient_id:state.mode==='demo'?'demo':state.session?.user.id,medicine_name:medicine,strength,dosage_form,quantity,city,latitude:point.lat,longitude:point.lng,radius_km,urgency,status:'open'};
try{if(state.mode==='demo'){req.id=uid();req.created_at=now();req.expires_at=hrs(12);req.targets=targetPharmacies(req,state.data.pharmacies);state.data.requests.unshift(req);saveDemo();toast(`Demo request created — ${req.targets.length} sample pharmacies targeted.`);}else{const {error}=await state.sb.from('medicine_requests').insert(req);if(error)throw error;await refreshLive();toast('Your request has been submitted to matching pharmacies.');}state.modal=null;state.page='requests';render();}catch(e){errorIn('requestError',e.message||'Could not create request.');}}
async function submitResponse(form){const m=state.modal;const req=state.data.requests.find(r=>r.id===m.id)||state.data.incoming?.find(r=>r.id===m.id);if(!req){errorIn('responseError','Request no longer available.');return;}const d=new FormData(form);const note=String(d.get('note')||'').trim().slice(0,240);try{if(state.mode==='demo'){let resp=state.data.responses.find(x=>x.request_id===req.id&&x.pharmacy_id===state.activePharmacy);if(resp){resp.status=m.status;resp.note=note||'Sample status, not real stock.';resp.confirmed_at=now();resp.expires_at=hrs(.5);}else state.data.responses.push({id:uid(),request_id:req.id,pharmacy_id:state.activePharmacy,status:m.status,note:note||'Sample status, not real stock.',confirmed_at:now(),expires_at:hrs(.5)});saveDemo();toast('Demo response saved. Switch to My requests to see it.');}else{if(!d.get('verified_stock'))return errorIn('responseError','Confirm that you personally checked the requested stock.');const target=state.data.incoming?.find(x=>x.id===req.id&&x.pharmacy_id===state.activePharmacy);if(!target?.target_id)throw Error('No matching pharmacy target.');const {error}=await state.sb.rpc('respond_to_request',{p_target_id:target.target_id,p_status:m.status,p_note:note});if(error)throw error;await refreshLive();toast('Your stock confirmation has been recorded.');}state.modal=null;render();}catch(e){errorIn('responseError',e.message||'Unable to save your response.');}}
async function submitPharmacy(form){const d=new FormData(form);const city=d.get('city'),point=cityPoint(city);const row={name:String(d.get('name')).trim(),city,address:String(d.get('address')).trim(),phone:String(d.get('phone')||'').trim(),license:String(d.get('license')).trim(),lat:point.lat,lng:point.lng,is_verified:false,is_active:true};try{if(state.mode==='demo'){row.id=uid();row.stock=[];state.data.pharmacies.push(row);saveDemo();toast('Sample pharmacy added for review.');}else{const {error}=await state.sb.from('pharmacies').insert(row);if(error)throw error;await refreshLive();toast('Pharmacy added as pending verification.');}state.modal=null;render();}catch(e){errorIn('pharmacyError',e.message||'Could not add pharmacy.');}}
async function submitAuth(form){if(!state.sb)return errorIn('authError','Supabase is not configured.');const d=new FormData(form),email=String(d.get('email')||'').trim(),password=String(d.get('password')||'');try{const result=state.authMode==='signup'?await state.sb.auth.signUp({email,password,options:{data:{display_name:String(d.get('display_name')||'').trim()}}}):await state.sb.auth.signInWithPassword({email,password});if(result.error)throw result.error;state.modal=null;if(state.authMode==='signup'&&!result.data.session)toast('Check your email and confirm your account before signing in.');else toast('Signed in successfully.');await refreshLive();render();}catch(e){errorIn('authError',e.message||'Authentication failed.');}}
async function cancelRequest(id){const r=state.data.requests.find(x=>x.id===id);if(!r||!requestOpen(r))return;try{if(state.mode==='demo'){r.status='cancelled';saveDemo();}else{const {error}=await state.sb.rpc('cancel_medicine_request',{p_request_id:id});if(error)throw error;await refreshLive();}render();toast('Request cancelled.');}catch(e){showError(e);}}
async function toggleVerify(id){const p=pharmacyById(id);if(!p)return;if(state.mode==='live'&&state.profile?.role!=='admin')return;try{if(state.mode==='demo'){p.is_verified=!p.is_verified;saveDemo();}else{const {error}=await state.sb.from('pharmacies').update({is_verified:!p.is_verified}).eq('id',id);if(error)throw error;await refreshLive();}render();toast(p.is_verified?'Pharmacy marked as verified.':'Pharmacy marked as pending.');}catch(e){showError(e);}}
function handleAction(el){const act=el.dataset.action;const data=el.dataset;if(act==='new-request'){openModal('request',{medicine:data.medicine||''});return;}if(act==='close-modal'||act==='dismiss-modal'){state.modal=null;render();return;}if(act==='select-medicine'){state.term=data.medicine;openModal('request',{medicine:data.medicine,strength:data.strength,form:data.form});return;}if(act==='respond'){openModal('respond',{id:data.id,status:data.status});return;}if(act==='cancel-request'){if(confirm('Cancel this medicine request?'))cancelRequest(data.id);return;}if(act==='toggle-verify'){if(confirm('Have you independently verified the pharmacy licence and details?'))toggleVerify(data.id);return;}if(act==='new-pharmacy'){if(state.mode==='demo'||state.profile?.role==='admin')openModal('pharmacy');return;}if(act==='account'){openModal('account');return;}if(act==='login'){state.authMode='signin';openModal('auth');return;}if(act==='auth-switch'){state.authMode=data.authmode;openModal('auth');return;}if(act==='signout'){state.sb?.auth.signOut().then(()=>{state.session=null;state.profile=null;refreshLive().then(render);toast('Signed out.');}).catch(showError);return;}if(act==='setup'){openModal('setup');return;}if(act==='reset-demo'){if(confirm('Reset all sample requests, pharmacy responses and demo changes?')){try{localStorage.removeItem('medifind_demo_v01');}catch{}state.data=sampleDB();state.modal=null;state.page='home';render();toast('Demo data reset.');}return;}if(act==='refresh'){if(state.mode==='live')refreshLive().then(()=>{render();toast('Data updated.');}).catch(showError);else{render();toast('Demo data is up to date.');}return;}}
document.addEventListener('click',e=>{const navEl=e.target.closest('[data-nav]');if(navEl){e.preventDefault();nav(navEl.dataset.nav);return;}const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render();return;}const act=e.target.closest('[data-action]');if(act){if(act.dataset.action==='dismiss-modal'&&e.target!==act)return;e.preventDefault();handleAction(act);}});
document.addEventListener('change',e=>{if(e.target.id==='pharmacyPicker'){state.activePharmacy=e.target.value;render();}});
document.addEventListener('submit',e=>{const id=e.target.id;if(!['searchForm','requestForm','responseForm','pharmacyForm','authForm'].includes(id))return;e.preventDefault();if(id==='searchForm'){const d=new FormData(e.target);state.term=String(d.get('medicine')||'').trim();state.city=String(d.get('city')||'Maharagama');state.page='find';state.filter='all';render();window.scrollTo({top:0,behavior:'smooth'});return;}if(id==='requestForm')submitRequest(e.target);if(id==='responseForm')submitResponse(e.target);if(id==='pharmacyForm')submitPharmacy(e.target);if(id==='authForm')submitAuth(e.target);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;render();}});
// Live Supabase backend: uses browser publishable key and SQL row-level security.
async function initLive(){try{await import('./config.js');}catch{render();return;}const config=window.MEDIFIND_CONFIG;if(!config?.supabaseUrl?.startsWith('https://')||!config?.supabaseAnonKey||config.supabaseAnonKey.includes('YOUR_')){render();return;}try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.49.8?bundle');state.sb=createClient(config.supabaseUrl,config.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});state.mode='live';state.data={pharmacies:[],requests:[],responses:[],incoming:[]};const {data:{session}}=await state.sb.auth.getSession();state.session=session;await refreshLive();state.sb.auth.onAuthStateChange((_event,session)=>{state.session=session;setTimeout(()=>refreshLive().then(render).catch(showError),0);});render();}catch(e){console.error('Supabase connection failed',e);state.mode='demo';state.sb=null;state.data=loadDemo();render();toast('Live mode unavailable. Running safe demo only.');}}
async function refreshLive(){if(state.mode!=='live'||!state.sb)return;const sb=state.sb;const {data:auth}=await sb.auth.getSession();state.session=auth.session;state.profile=null;state.assignedPharmacies=[];if(state.session){const {data:profile,error:profileError}=await sb.from('profiles').select('id,display_name,role').eq('id',state.session.user.id).maybeSingle();if(profileError)throw profileError;state.profile=profile;}
const {data:pharmacies,error:pharmErr}=await sb.from('pharmacies').select('id,name,city,address,phone,license,lat,lng,is_verified,is_active').order('name');if(pharmErr)throw pharmErr;
let requests=[],responses=[],incoming=[];
if(state.session){const [{data:reqs,error:reqErr},{data:res,error:resErr},{data:members,error:membersErr},{data:targets,error:targetsErr}]=await Promise.all([
 sb.from('medicine_requests').select('id,patient_id,medicine_name,strength,dosage_form,quantity,city,latitude,longitude,radius_km,urgency,status,created_at,expires_at').order('created_at',{ascending:false}),
 sb.from('pharmacy_responses').select('id,request_id,pharmacy_id,status,note,confirmed_at,expires_at'),
 sb.from('pharmacy_staff').select('pharmacy_id,pharmacies(id,name,city,is_verified,is_active)').eq('user_id',state.session.user.id).eq('is_active',true),
 sb.rpc('get_incoming_requests')
]);if(reqErr)throw reqErr;if(resErr)throw resErr;if(membersErr)throw membersErr;if(targetsErr)throw targetsErr;requests=reqs||[];responses=res||[];state.assignedPharmacies=(members||[]).map(m=>m.pharmacies).filter(Boolean);incoming=(targets||[]).map(x=>({id:x.request_id,target_id:x.target_id,pharmacy_id:x.pharmacy_id,medicine_name:x.medicine_name,strength:x.strength,dosage_form:x.dosage_form,quantity:x.quantity,city:x.city,urgency:x.urgency,created_at:x.created_at,expires_at:x.expires_at,status:x.status}));if(!state.assignedPharmacies.some(p=>p.id===state.activePharmacy))state.activePharmacy=state.assignedPharmacies[0]?.id||'';}
state.data={pharmacies:pharmacies||[],requests,responses,incoming};}
render();initLive();
if('serviceWorker' in navigator&&location.protocol!=='file:'){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(err=>console.info('PWA offline cache unavailable',err)));}
